5	/**
6	 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局处理器转为响应体。
7	 */
8	public class ApiException extends RuntimeException {
9	
10	    private final HttpStatus status;
11	    private final String code;
12	
13	    public ApiException(HttpStatus status, String code, String message) {
14	        super(message);
15	        this.status = status;
16	        this.code = code;
17	    }
18	
19	    public HttpStatus status() {
20	        return status;
21	    }
22	
23	    public String code() {
24	        return code;
25	    }
