2	
3	import java.sql.Timestamp;
4	import java.time.Clock;
5	import java.time.Instant;
6	import java.util.List;
7	
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Propagation;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	/**
14	 * 防误闭锁评估：基于合成闭锁规则库与设备实时状态，对操作步骤做五防校验。
15	 * 规则：带负荷拉合刀闸、带电挂接地线、带地线送电直接闭锁；
16	 * 母线停电须先断开全部出线开关，顺序违例整步拒绝。
17	 */
18	@Service
19	public class InterlockService {
20	
21	    /** 带负荷拉合刀闸 */
22	    public static final String LOAD_DISCONNECTOR = "LOAD_DISCONNECTOR";
23	    /** 带电挂接地线 */
24	    public static final String LIVE_GROUND = "LIVE_GROUND";
25	    /** 带地线送电 */
26	    public static final String GROUNDED_ENERGIZE = "GROUNDED_ENERGIZE";
27	    /** 母线停电顺序违例 */
28	    public static final String BUS_OUTAGE_SEQUENCE = "BUS_OUTAGE_SEQUENCE";
29	
30	    private final JdbcTemplate jdbc;
31	    private final Clock clock;
32	
33	    public InterlockService(JdbcTemplate jdbc, Clock businessClock) {
34	        this.jdbc = jdbc;
35	        this.clock = businessClock;
36	    }
37	
38	    /**
39	     * 记录闭锁命中，独立事务提交：即使业务操作被拒绝回滚，命中轨迹仍保留可复算。
40	     *
41	     * @param ticketId 关联操作票主键，可为空
42	     * @param stepSeq  关联步序，可为空
43	     * @param ruleCode 命中的规则编码
44	     * @param detail   命中详情
45	     */
46	    @Transactional(propagation = Propagation.REQUIRES_NEW)
47	    public void recordHit(Long ticketId, Integer stepSeq, String ruleCode, String detail) {
48	        jdbc.update(
49	                "INSERT INTO interlock_hit (ticket_id, step_seq, rule_code, detail, created_at) VALUES (?, ?, ?, ?, ?)",
50	                ticketId, stepSeq, ruleCode, detail, Timestamp.from(Instant.now(clock)));
51	    }
52	
53	    /**
54	     * 评估一步操作是否被闭锁。
55	     *
56	     * @param operationType 操作类型
57	     * @param deviceId      操作设备编号
58	     * @return 评估结果，blocked=true 表示闭锁拒绝
59	     */
60	    public InterlockResult evaluate(String operationType, String deviceId) {
61	        String intervalId = jdbc.query(
62	                        "SELECT interval_id FROM device_state WHERE device_id = ?",
63	                        (rs, rowNum) -> rs.getString(1), deviceId)
64	                .stream().findFirst().orElse(null);
65	        if (intervalId == null) {
66	            return InterlockResult.pass();
67	        }
68	        return switch (operationType) {
69	            case "OPEN_DISCONNECTOR", "CLOSE_DISCONNECTOR" -> checkLoadDisconnector(intervalId);
70	            case "APPLY_GROUND" -> checkLiveGround(intervalId);
71	            case "CLOSE_BREAKER" -> checkGroundedEnergize(intervalId);
72	            case "BUS_OUTAGE" -> checkBusOutageSequence(intervalId);
73	            default -> InterlockResult.pass();
74	        };
75	    }
76	
77	    /** 带负荷拉合刀闸：间隔内开关合位时禁止拉合刀闸。 */
78	    private InterlockResult checkLoadDisconnector(String intervalId) {
79	        List<String> closedBreakers = closedBreakers(intervalId);
80	        if (ruleEnabled(LOAD_DISCONNECTOR) && !closedBreakers.isEmpty()) {
81	            return InterlockResult.block(LOAD_DISCONNECTOR,
82	                    "带负荷拉合刀闸：间隔 " + intervalId + " 开关 " + closedBreakers + " 仍在合位");
83	        }
84	        return InterlockResult.pass();
85	    }
86	
87	    /** 带电挂接地线：间隔内开关合位（设备带电）时禁止挂接地线。 */
88	    private InterlockResult checkLiveGround(String intervalId) {
89	        List<String> closedBreakers = closedBreakers(intervalId);
90	        if (ruleEnabled(LIVE_GROUND) && !closedBreakers.isEmpty()) {
91	            return InterlockResult.block(LIVE_GROUND,
92	                    "带电挂接地线：间隔 " + intervalId + " 开关 " + closedBreakers + " 仍在合位");
93	        }
94	        return InterlockResult.pass();
95	    }
96	
97	    /** 带地线送电：间隔内接地线未拆时禁止合开关。 */
98	    private InterlockResult checkGroundedEnergize(String intervalId) {
99	        List<String> appliedGrounds = jdbc.query(
100	                "SELECT device_id FROM device_state WHERE interval_id = ? AND device_type = 'GROUND' AND state = 'APPLIED'",
101	                (rs, rowNum) -> rs.getString(1), intervalId);
102	        if (ruleEnabled(GROUNDED_ENERGIZE) && !appliedGrounds.isEmpty()) {
103	            return InterlockResult.block(GROUNDED_ENERGIZE,
104	                    "带地线送电：间隔 " + intervalId + " 接地线 " + appliedGrounds + " 未拆除");
105	        }
106	        return InterlockResult.pass();
107	    }
108	
109	    /** 母线停电顺序：须先断开全部出线开关，否则整步拒绝。 */
110	    private InterlockResult checkBusOutageSequence(String intervalId) {
111	        List<String> closedBreakers = closedBreakers(intervalId);
112	        if (ruleEnabled(BUS_OUTAGE_SEQUENCE) && !closedBreakers.isEmpty()) {
113	            return InterlockResult.block(BUS_OUTAGE_SEQUENCE,
114	                    "母线停电顺序违例：母线 " + intervalId + " 出线开关 " + closedBreakers + " 未全部断开");
115	        }
116	        return InterlockResult.pass();
117	    }
118	
119	    private List<String> closedBreakers(String intervalId) {
120	        return jdbc.query(
121	                "SELECT device_id FROM device_state WHERE interval_id = ? AND device_type = 'BREAKER' AND state = 'CLOSED'",
122	                (rs, rowNum) -> rs.getString(1), intervalId);
123	    }
124	
125	    private boolean ruleEnabled(String ruleCode) {
126	        Boolean enabled = jdbc.query(
127	                        "SELECT enabled FROM interlock_rule WHERE rule_code = ?",
128	                        (rs, rowNum) -> rs.getBoolean(1), ruleCode)
129	                .stream().findFirst().orElse(null);
130	        return enabled == null || enabled;
131	    }
132	}
