336	        assertEquals(1, conflict.get(), "失败方必须收到唯一冲突");
337	        assertEquals(1, jdbc.queryForObject(
338	                "SELECT COUNT(*) FROM interval_execution_lock WHERE interval_id = 'INT-1101'", Integer.class));
339	    }
