        long ticketB = draft("b-batch-b", "INT-1102", step("OPEN_BREAKER", "BR-X", "OPEN"));
        // GL-0002 可用但 GL-0001 已借出：整批拒绝，GL-0002 不得被占用
        ApiException ex = assertThrows(ApiException.class, () -> groundWireService.borrow(
